import{_ as t,o,c as r,a2 as a}from"./chunks/framework.CT6jiXWi.js";const g=JSON.parse('{"title":"Features","description":"","frontmatter":{},"headers":[],"relativePath":"federation/reference/features.md","filePath":"federation/reference/features.md","lastUpdated":1783784358000}'),d={name:"federation/reference/features.md"};function s(n,e,c,i,l,h){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h1><p>What <code>cds-data-federation</code> does today, grouped by capability. Every entry on this page is available in the current release. Annotation syntax and option reference are in <a href="./annotations.html">Annotations</a>; scenario names follow <a href="./../concepts/cross-service-scenarios.html">Cross-Service Scenarios</a>.</p><h2 id="consumption-views" tabindex="-1">Consumption views <a class="header-anchor" href="#consumption-views" aria-label="Permalink to &quot;Consumption views&quot;">​</a></h2><p>The CDS projection on a remote entity defines the schema contract — what fields, what shape, what renames. See <a href="./../concepts/consumption-views.html">Consumption Views</a> for the full pattern catalog.</p><table tabindex="0"><thead><tr><th>Pattern</th><th>Example</th><th>Notes</th></tr></thead><tbody><tr><td><strong>Wildcard projection</strong></td><td><code>as projection on remote.X { * }</code></td><td>All remote fields projected.</td></tr><tr><td><strong>Column restriction + field renames</strong></td><td><code>as projection on remote.X { ID as productId, price as unitPrice }</code></td><td>Bidirectional local ↔ remote mapping. <code>$select</code> on the remote is restricted to the projected set.</td></tr><tr><td><strong>Excluding columns</strong></td><td><code>as projection on remote.X excluding { modifiedAt }</code></td><td>Excluded fields are omitted from <code>$select</code> and absent from responses.</td></tr><tr><td><strong>Static <code>where</code> clause</strong></td><td><code>as projection on remote.X where status = &#39;active&#39;</code></td><td>Filter is injected into every remote query for this entity. Composes with client filters.</td></tr><tr><td><strong>Entity-level rename</strong></td><td><code>entity Suppliers as projection on remote.Customers { … }</code></td><td>Project a remote entity under a different local name and domain purpose.</td></tr></tbody></table><h2 id="delegate-strategy" tabindex="-1">Delegate strategy <a class="header-anchor" href="#delegate-strategy" aria-label="Permalink to &quot;Delegate strategy&quot;">​</a></h2><p>Transparent live proxy. Annotate a consumption view with <code>@federation.delegate</code> and the plugin forwards reads to the remote service at request time. Reference: <a href="./annotations.html"><code>@federation.delegate</code></a>.</p><table tabindex="0"><thead><tr><th>Capability</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Declarative handler registration</strong></td><td>Adding <code>@federation.delegate</code> to a projection wires the read handler automatically.</td></tr><tr><td><strong>Query translation</strong></td><td><code>$select</code>, <code>$filter</code>, <code>$orderby</code>, and <code>$expand</code> are translated through the CDS projection chain so client-side names always refer to the local model.</td></tr><tr><td><strong>Column-restricted fetch</strong></td><td>Requests to the remote only include fields the consumption view projects.</td></tr><tr><td><strong>Server-driven paging</strong></td><td>When a remote caps responses below the client&#39;s requested <code>$top</code> (e.g. Northwind&#39;s 20-row default), the handler loops <code>$top</code>/<code>$skip</code> until the client is satisfied. <code>@odata.count</code> is preserved.</td></tr><tr><td><strong>Full query passthrough</strong></td><td>Arbitrary combinations of <code>$filter</code> / <code>$orderby</code> / <code>$select</code> / <code>$top</code> / <code>$skip</code> / <code>$expand</code> work on any delegate entity, V4 and V2.</td></tr><tr><td><strong><a href="./../concepts/cross-service-scenarios.html">Delegated expand</a></strong></td><td>Same-remote <code>$expand</code> is handled by CAP&#39;s native query translation.</td></tr><tr><td><strong><a href="./../concepts/cross-service-scenarios.html#cross-service-expand-local-remote">Cross-service expand: local → remote</a></strong></td><td>When a local entity <code>$expand</code>s to a delegate entity, the plugin batch-fetches from the remote and stitches results — including cross-provider and composite-key cases.</td></tr><tr><td><strong><a href="./../concepts/cross-service-scenarios.html#cross-service-expand-remote-local">Cross-service expand: remote → local</a></strong></td><td>When a delegate entity <code>$expand</code>s to a local entity, the plugin forwards the remote portion, queries local for the targets, and stitches. <code>$filter</code> / <code>$orderby</code> / <code>$top</code> inside the expand are respected.</td></tr><tr><td><strong>Navigation path filters</strong></td><td><code>$filter</code> through renamed or cross-service associations (e.g. <code>buyer/name eq &#39;Acme&#39;</code>, or <code>LocalEntity/Name eq &#39;X&#39;</code> on a delegate with a local backlink) is translated for same-service and both cross-service directions (to-one and lambda).</td></tr><tr><td><strong>Cross-service navigation</strong></td><td>URL navigation across a local/remote boundary — <code>/Reviews(id)/product</code> or <code>/Customers(&#39;C001&#39;)/bookmarks</code> — is resolved transparently. Supports <code>$select</code> and <code>$filter</code> on the target.</td></tr><tr><td><strong>Opt-in CUD forwarding</strong></td><td>Writes are off by default. Enable all three with <code>writable: true</code> or pick individual flags (<code>create</code>, <code>update</code>, <code>delete</code>). Synchronous — clients get the remote&#39;s response.</td></tr><tr><td><strong>Error propagation</strong></td><td>Remote status codes, messages, and context reach the client.</td></tr></tbody></table><h2 id="replicate-strategy" tabindex="-1">Replicate strategy <a class="header-anchor" href="#replicate-strategy" aria-label="Permalink to &quot;Replicate strategy&quot;">​</a></h2><p>Scheduled sync that copies remote data into the local database. Once replicated, queries run fully locally — joinable, aggregatable, offline-capable. Reference: <a href="./annotations.html"><code>@federation.replicate</code></a>. Every replicate entity binds to an entity-shape job on <a href="/cds-data/pipeline/">cds-data-pipeline</a>; pipeline intent is <strong>derived</strong> from the config shape (see <a href="/cds-data/pipeline/guide/concepts/inference.html">inference rules</a>).</p><table tabindex="0"><thead><tr><th>Capability</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Full sync</strong></td><td>Truncate (multi-source aware) and replace.</td></tr><tr><td><strong>Delta sync</strong></td><td>Three delta modes: timestamp-based, key-based, and datetime-fields via adapter options.</td></tr><tr><td><strong>Streaming batch reads</strong></td><td>Async-generator pipeline with configurable batch size. Only projected columns are fetched.</td></tr><tr><td><strong>Idempotent writes</strong></td><td>Every batch is applied via <code>UPSERT</code> — safe to re-run.</td></tr><tr><td><strong>Auto-persistence</strong></td><td><code>replicate</code> entities automatically get <code>@cds.persistence.table: true</code>; no manual table setup.</td></tr><tr><td><strong>Pipeline events</strong></td><td><code>before</code> / <code>on</code> / <code>after</code> hooks on <code>PIPELINE.READ</code>, <code>PIPELINE.MAP</code>, <code>PIPELINE.WRITE</code> for custom transformation or filtering logic — see the <a href="/cds-data/pipeline/reference/management-service.html#event-hooks">pipeline event hooks reference</a>.</td></tr><tr><td><strong>Rename mapping during MAP</strong></td><td>Field renames from the consumption view are applied during the MAP phase — no per-entity mapping code.</td></tr><tr><td><strong>Replicated aspect</strong></td><td><code>lastReplicatedAt</code> / <code>lastReplicatedBy</code> are auto-populated on every record.</td></tr></tbody></table><h2 id="caching" tabindex="-1">Caching <a class="header-anchor" href="#caching" aria-label="Permalink to &quot;Caching&quot;">​</a></h2><p>Two optional strategies on <code>@federation.delegate</code> (and a rarely useful response cache on replicate). See <a href="./../integration/caching.html">Integration → Caching</a>.</p><table tabindex="0"><thead><tr><th>Capability</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Response cache</strong> (<code>strategy: &#39;response&#39;</code>, default)</td><td>Wraps the remote READ with <a href="https://github.com/mikezaschka/cds-caching" target="_blank" rel="noreferrer"><code>cds-caching</code></a>; cache key = full query signature.</td></tr><tr><td><strong>Entity cache</strong> (<code>strategy: &#39;entity&#39;</code>)</td><td>On TTL miss, runs <a href="/cds-data/pipeline/"><code>cds-data-pipeline</code></a> to fill a SQLite table with the full projected entity; any READ CQN hits SQLite until TTL. <strong>One SQLite file per tenant</strong> when <code>data-federation-cache</code> is configured. Falls back to live delegate on errors.</td></tr><tr><td><strong>Per-entity TTL</strong></td><td><code>cache: { ttl: 60000 }</code> on either strategy.</td></tr><tr><td><strong>Tag-based invalidation</strong></td><td><code>response</code> only — auto-tag <code>federation:&lt;entityName&gt;</code>, static/dynamic/template tags via <code>cds-caching</code>.</td></tr><tr><td><strong>Backend flexibility</strong></td><td><code>response</code>: in-memory, Redis, HANA, … via <code>cds-caching</code>. <code>entity</code>: primary <code>db</code> or optional <code>cds.requires.&#39;data-federation-cache&#39;</code> SQLite.</td></tr><tr><td><strong>Configurable cache service</strong></td><td><code>cache.service</code> selects a <code>cds-caching</code> instance (<code>response</code> only).</td></tr><tr><td><strong>Hit / miss metrics</strong></td><td><code>cds-caching</code> statistics API (<code>response</code>).</td></tr><tr><td><strong>Graceful degradation</strong></td><td>Missing <code>cds-caching</code> → skip <code>response</code> with warning. Missing pipeline/SQLite → skip <code>entity</code> with warning; live delegate continues.</td></tr></tbody></table><h2 id="cross-service-scenarios" tabindex="-1">Cross-service scenarios <a class="header-anchor" href="#cross-service-scenarios" aria-label="Permalink to &quot;Cross-service scenarios&quot;">​</a></h2><p>Summary — see <a href="./../concepts/cross-service-scenarios.html">Cross-Service Scenarios</a> for the full scenario reference.</p><table tabindex="0"><thead><tr><th>Scenario</th><th>Supported</th></tr></thead><tbody><tr><td><a href="./../concepts/cross-service-scenarios.html">Delegated expand</a></td><td>Yes (CAP-native).</td></tr><tr><td><a href="./../concepts/cross-service-scenarios.html#cross-service-expand-local-remote">Cross-service expand: local → remote</a></td><td>Yes — including to-many, composite keys, cross-provider, nested expand, <code>$filter</code> / <code>$orderby</code> / <code>$top</code> / <code>$skip</code> inside the expand, and lambda operators.</td></tr><tr><td><a href="./../concepts/cross-service-scenarios.html#cross-service-expand-remote-local">Cross-service expand: remote → local</a></td><td>Yes — including per-parent <code>$top</code> limiting.</td></tr><tr><td><a href="./../concepts/cross-service-scenarios.html#cross-service-expand-cross-provider">Cross-service expand: cross-provider</a></td><td>Yes.</td></tr><tr><td><a href="./../concepts/cross-service-scenarios.html#cross-service-navigation-local-remote">Cross-service navigation: local → remote</a></td><td>Yes — <code>$select</code> and <code>$filter</code> on the target supported.</td></tr><tr><td><a href="./../concepts/cross-service-scenarios.html#cross-service-navigation-remote-local">Cross-service navigation: remote → local</a></td><td>Yes.</td></tr></tbody></table><h2 id="cqn-safety" tabindex="-1">CQN safety <a class="header-anchor" href="#cqn-safety" aria-label="Permalink to &quot;CQN safety&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Capability</th><th>What it does</th></tr></thead><tbody><tr><td><strong>CQN clone on mutation</strong></td><td>Delegate handlers clone queries before any modification — changes never leak back into CAP&#39;s request pipeline.</td></tr></tbody></table><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Capability</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Annotation-driven</strong></td><td>Zero configuration for standard scenarios — <code>@federation.delegate</code> or <code>@federation.replicate</code> on a consumption view is enough.</td></tr><tr><td><strong>Profile-based overrides</strong></td><td>Different settings per CAP environment profile (<code>[development]</code>, <code>[production]</code>, …) via the native <code>cds.env</code> mechanism.</td></tr><tr><td><strong>Sensible defaults</strong></td><td>Read-only CUD for delegate; delta mode for replicate; batch size 1000; 10-minute replicate schedule.</td></tr></tbody></table>',21)])])}const m=t(d,[["render",s]]);export{g as __pageData,m as default};
